    # Define a recursive function with memoization to calculate the number of sequences
    @lru_cache(None)
    def dp(remaining_holes, remaining_balls):
        if len(remaining_balls) == 0:
            return 1
        total_sequences = 0
        for hole in range(1, n + 1):
            if hole in remaining_balls and hole <= remaining_holes[hole]:
                # Place the ball in this hole and remove it from consideration
                new_remaining_holes = remaining_holes.copy()
                del new_remaining_holes[hole]
                total_sequences += dp(new_remaining_holes, tuple(sorted([d for d in remaining_balls if d != hole])))
        return total_sequences

    # Initialize the holes with their capacities based on ball diameters
    holes = {i: n - i + 1 for i in range(1, n + 1)}

    # Place balls of given diameters immediately into appropriate holes
