        return (a + b < d) and (b + c < d) and (c + a < d) and (a + b + c > d)

    total_configurations = 0
    valid_configurations = 0

    # Iterate over all possible choices for the large circle number.
    for d in range(4, n+1):
        # Iterate over all combinations of three numbers from the remaining set to place in small circles.
        for a in range(1, d-2):
            for b in range(a+1, d-1):
                for c in range(b+1, d):
                    if is_valid_configuration(a, b, c, d):
                        valid_configurations += 1
                    total_configurations += 1

    # Calculate the probability.
    probability = valid_configurations / total_configurations
    return k * probability

