def calculate_submerged_volume(h, r, s):
    # Calculate the height of water in the glass when it is 3/4 full
    initial_water_height = (3/4) * h

    # The cube's space diagonal length is equal to the diameter of the cylinder
    d = 2 * r
    a = d / math.sqrt(3)  # Side length of the cube that fits the given condition

    # Calculate the submerged part of the cube
    if s <= initial_water_height:
        submerged_volume = s ** 3
    else:
        submerged_volume = (s - (h - initial_water_height)) ** 3 + ((h - initial_water_height) * a ** 2 * math.sqrt(3) / 4)

    return round(submerged_volume, 1)

def solve_overflow(h, r, s):
    # Calculate the volume of water that would overflow
    overflow_volume = calculate_submerged_volume(h, r, s) - (h * math.pi * r ** 2)
    return max(0, overflow_volume)

